import {
    Column,
    CreateDateColumn,
    Entity,
    Index,
    JoinColumn,
    ManyToOne,
    PrimaryColumn,
} from 'typeorm';

import { User } from './user.entity.js';

/** One row per logged-in device. Holds the hash of that device's current refresh token. */
@Entity( 'sessions' )
export class Session {
    // Generated by SessionsService, because the id is part of the refresh token.
    @PrimaryColumn( 'uuid' )
    id: string;

    @Index()
    @Column( { name: 'user_id', type: 'uuid' } )
    userId: string;

    @ManyToOne( () => User, { onDelete: 'CASCADE' } )
    @JoinColumn( { name: 'user_id' } )
    user: User;

    @Column( { name: 'token_hash', type: 'varchar', length: 64 } )
    tokenHash: string;

    // The token this one replaced, to tell a concurrent refresh apart from token theft.
    @Column( { name: 'previous_token_hash', type: 'varchar', length: 64, nullable: true } )
    previousTokenHash: string | null;

    @Column( { name: 'rotated_at', type: 'timestamptz', nullable: true } )
    rotatedAt: Date | null;

    // Sliding expiry: pushed forward on every refresh.
    @Column( { name: 'expires_at', type: 'timestamptz' } )
    expiresAt: Date;

    @Column( { name: 'last_used_at', type: 'timestamptz' } )
    lastUsedAt: Date;

    @Column( { name: 'user_agent', type: 'varchar', length: 512, nullable: true } )
    userAgent: string | null;

    @Column( { type: 'varchar', length: 64, nullable: true } )
    ip: string | null;

    @CreateDateColumn( { name: 'created_at', type: 'timestamptz' } )
    createdAt: Date;
}
